"""
    build_steps.py - Read build task configuration YAML file and create a build task list.
"""

from yaml import safe_load

# The code is generated by AI.
# The documentation is written by me.
def get_build_steps(yaml_path: str, ci_mode: bool) -> list:
    """
        This function reads a build steps configuration and stores fitting steps in a list.
        The yaml_path parameter is the path to the yaml build steps configuration.
        The ci_mode parameter specifies whether this program is running in a continuous integration or locally, which may change build commands.
        For instance compile commands are often generated locally for static analyzers (like clangd) but not in CI.
        Configuration format is explained in the example config under examples/config.yaml
    """
    with open(yaml_path, 'r', encoding='utf-8') as f:
        config = safe_load(f)
    
    raw_steps = config.get("build", {}).get("steps", [])
    processed_steps = []
    
    for step in raw_steps:
        env = step.get("environment", "both").lower()
        
        if ci_mode and env == "local":
            continue
            
        if not ci_mode and env == "ci":
            continue
            
        description = step.get("description")
        cmd = step.get("cmd", "")
        log_base = step.get("log_file_name_base")
        rwd = step.get("rwd")

        processed_steps.append((description, cmd, log_base, rwd))
        
    return processed_steps

